const POLYGON_API_KEY = 'REPLACE_WITH_POLYGON_API_KEY';
const MARKETAUX_API_TOKEN = 'REPLACE_WITH_MARKETAUX_API_TOKEN';
const TELEGRAM_BOT_TOKEN = 'REPLACE_WITH_TELEGRAM_BOT_TOKEN';
const TELEGRAM_CHAT_ID = 'REPLACE_WITH_TELEGRAM_CHAT_ID';

// Stop execution early if placeholders were not updated.
for (const [key, value] of Object.entries({
  POLYGON_API_KEY,
  MARKETAUX_API_TOKEN,
  TELEGRAM_BOT_TOKEN,
  TELEGRAM_CHAT_ID,
})) {
  if (String(value).startsWith('REPLACE_WITH_')) {
    throw new Error(`Please update ${key} in the "Build Request URLs" Code node before activating this workflow.`);
  }
}

function ymd(date) {
  return date.toISOString().slice(0, 10);
}

function shiftDays(base, days) {
  const d = new Date(base);
  d.setUTCDate(d.getUTCDate() + days);
  return d;
}

function aggUrl(symbol, timespan, fromDate, toDate) {
  const encoded = encodeURIComponent(symbol);
  return `https://api.polygon.io/v2/aggs/ticker/${encoded}/range/1/${timespan}/${ymd(fromDate)}/${ymd(toDate)}?adjusted=true&sort=asc&limit=50000&apiKey=${POLYGON_API_KEY}`;
}

const now = new Date();
const spx = 'I:SPX';
const vix = 'I:VIX';

const hourlyFrom = shiftDays(now, -75);   // enough history for recent hourly regime
const dailyFrom  = shiftDays(now, -450);  // about 18 months
const weeklyFrom = shiftDays(now, -365 * 6);

const publishedAfter = new Date(now.getTime() - (36 * 60 * 60 * 1000)).toISOString().slice(0, 16);
const marketSearch = '("S&P 500"|SPX|VIX|"Federal Reserve"|inflation|yields|earnings)';
const newsUrl =
  'https://api.marketaux.com/v1/news/all'
  + `?api_token=${MARKETAUX_API_TOKEN}`
  + '&language=en'
  + '&countries=us'
  + '&must_have_entities=true'
  + '&group_similar=true'
  + '&filter_entities=false'
  + '&limit=3'
  + `&search=${encodeURIComponent(marketSearch)}`
  + `&published_after=${encodeURIComponent(publishedAfter)}`;

return [{
  json: {
    polygonApiKey: POLYGON_API_KEY,
    marketauxApiToken: MARKETAUX_API_TOKEN,
    telegramBotToken: TELEGRAM_BOT_TOKEN,
    telegramChatId: TELEGRAM_CHAT_ID,
    scheduleTimezone: 'America/Chicago',
    spxHourlyUrl: aggUrl(spx, 'hour', hourlyFrom, now),
    spxDailyUrl: aggUrl(spx, 'day', dailyFrom, now),
    spxWeeklyUrl: aggUrl(spx, 'week', weeklyFrom, now),
    vixHourlyUrl: aggUrl(vix, 'hour', hourlyFrom, now),
    vixDailyUrl: aggUrl(vix, 'day', dailyFrom, now),
    vixWeeklyUrl: aggUrl(vix, 'week', weeklyFrom, now),
    newsUrl
  }
}];

function firstJson(nodeName) {
  return $(nodeName).first().json;
}

function getBars(nodeName) {
  const payload = firstJson(nodeName);
  return Array.isArray(payload.results) ? payload.results : [];
}

function toCloses(bars) {
  return bars
    .filter(b => b && typeof b.c === 'number')
    .map(b => ({ t: b.t, c: b.c }));
}

function returnsFromBars(bars) {
  const closes = toCloses(bars);
  const out = [];
  for (let i = 1; i < closes.length; i++) {
    const prev = closes[i - 1].c;
    const cur = closes[i].c;
    if (prev > 0 && Number.isFinite(cur) && Number.isFinite(prev)) {
      out.push((cur / prev) - 1);
    }
  }
  return out;
}

function mean(arr) {
  if (!arr.length) return 0;
  return arr.reduce((a, b) => a + b, 0) / arr.length;
}

function std(arr) {
  if (arr.length < 2) return 0;
  const m = mean(arr);
  const v = arr.reduce((s, x) => s + Math.pow(x - m, 2), 0) / (arr.length - 1);
  return Math.sqrt(Math.max(v, 0));
}

function clamp(x, lo, hi) {
  return Math.min(hi, Math.max(lo, x));
}

function momentumZ(bars, lookbackBars, volWindowBars) {
  const closes = toCloses(bars);
  const rets = returnsFromBars(bars);
  if (closes.length < lookbackBars + 1 || rets.length < volWindowBars) return 0;
  const latest = (closes[closes.length - 1].c / closes[closes.length - 1 - lookbackBars].c) - 1;
  const vol = std(rets.slice(-volWindowBars)) * Math.sqrt(Math.max(lookbackBars, 1));
  if (!Number.isFinite(vol) || vol <= 1e-9) return 0;
  return clamp(latest / vol, -3, 3);
}

function latestClose(bars) {
  const closes = toCloses(bars);
  return closes.length ? closes[closes.length - 1].c : null;
}

function normalCdf(x) {
  // Abramowitz-Stegun approximation
  const sign = x < 0 ? -1 : 1;
  const z = Math.abs(x) / Math.sqrt(2);
  const t = 1 / (1 + 0.3275911 * z);
  const a1 = 0.254829592;
  const a2 = -0.284496736;
  const a3 = 1.421413741;
  const a4 = -1.453152027;
  const a5 = 1.061405429;
  const erf = 1 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * Math.exp(-z * z);
  return 0.5 * (1 + sign * erf);
}

function pct(x) {
  return `${(x * 100).toFixed(2)}%`;
}

const config = firstJson('Build Request URLs');

const spxHourly = getBars('Get SPX Hourly');
const spxDaily = getBars('Get SPX Daily');
const spxWeekly = getBars('Get SPX Weekly');
const vixHourly = getBars('Get VIX Hourly');
const vixDaily = getBars('Get VIX Daily');
const vixWeekly = getBars('Get VIX Weekly');
const newsPayload = firstJson('Get Market News');
const newsItems = Array.isArray(newsPayload.data) ? newsPayload.data : [];

if (spxDaily.length < 30 || vixDaily.length < 30) {
  throw new Error('Not enough SPX/VIX history returned. Check your API keys/plan and symbol support.');
}

// Momentum / regime features from requested timeframes
const spxH = momentumZ(spxHourly, 6, 48);   // ~6 trading hours vs 2 trading days of hourly vol
const spxD = momentumZ(spxDaily, 5, 20);    // 1 week move
const spxW = momentumZ(spxWeekly, 4, 26);   // 1 month move
const vixH = momentumZ(vixHourly, 6, 48);
const vixD = momentumZ(vixDaily, 5, 20);
const vixW = momentumZ(vixWeekly, 4, 26);

// News sentiment: average across identified entities where available
const articleSentiments = newsItems.map(article => {
  const vals = Array.isArray(article.entities)
    ? article.entities
        .map(e => typeof e.sentiment_score === 'number' ? e.sentiment_score : null)
        .filter(v => v !== null)
    : [];
  return vals.length ? mean(vals) : 0;
});
const newsSentiment = articleSentiments.length ? mean(articleSentiments) : 0;

// Daily volatility baseline, adjusted by VIX level
const spxDailyReturns = returnsFromBars(spxDaily);
const baseSigma = std(spxDailyReturns.slice(-20)); // 20-day realized sigma
const latestVix = latestClose(vixDaily) ?? 20;
const vixRegimeMult = clamp(latestVix / 20, 0.70, 1.80);
const sigma = Math.max(baseSigma * vixRegimeMult, 0.003);

// Weighted directional score
const compositeScore =
  (0.40 * spxH) +
  (0.35 * spxD) +
  (0.25 * spxW) -
  (0.25 * vixH) -
  (0.20 * vixD) -
  (0.10 * vixW) +
  (0.20 * (newsSentiment * 3));

// Convert score into bounded expected return (mu)
const mu = Math.tanh(compositeScore / 4) * (0.60 * sigma);

// 1-sigma regime probabilities around flat return: Down < -σ, Sideways in [-σ,+σ], Up > +σ
const pDown = normalCdf((-sigma - mu) / sigma);
const pUp = 1 - normalCdf((sigma - mu) / sigma);
const pSideways = Math.max(0, 1 - pDown - pUp);

// Label
const probs = [
  { label: 'UP', value: pUp },
  { label: 'SIDEWAYS', value: pSideways },
  { label: 'DOWN', value: pDown },
].sort((a, b) => b.value - a.value);

const topLabel = probs[0].label;
const topProb = probs[0].value;

// Headlines
const headlines = newsItems.slice(0, 3).map((article, idx) => {
  const title = article.title || 'Untitled';
  const source = article.source || 'unknown source';
  return `${idx + 1}. ${title} (${source})`;
});

const summaryLines = [
  `Daily Market Trend Agent`,
  `${new Date().toISOString().slice(0, 10)}`,
  ``,
  `Prediction: ${topLabel} (${pct(topProb)})`,
  `1σ probabilities:`,
  `• Up: ${pct(pUp)}`,
  `• Sideways: ${pct(pSideways)}`,
  `• Down: ${pct(pDown)}`,
  ``,
  `Model stats:`,
  `• Expected next-day move (mu): ${pct(mu)}`,
  `• 1σ next-day band: ±${pct(sigma)}`,
  `• VIX close: ${latestVix.toFixed(2)}`,
  `• News sentiment: ${newsSentiment.toFixed(3)}`,
  ``,
  `Signals:`,
  `• SPX hourly z-score: ${spxH.toFixed(2)}`,
  `• SPX daily z-score: ${spxD.toFixed(2)}`,
  `• SPX weekly z-score: ${spxW.toFixed(2)}`,
  `• VIX hourly z-score: ${vixH.toFixed(2)}`,
  `• VIX daily z-score: ${vixD.toFixed(2)}`,
  `• VIX weekly z-score: ${vixW.toFixed(2)}`,
  ``,
  `Latest market headlines:`,
  ...(headlines.length ? headlines : ['No recent market headlines returned.']),
];

const telegramText = summaryLines.join('\n');
const telegramUrl =
  `https://api.telegram.org/bot${config.telegramBotToken}/sendMessage`
  + `?chat_id=${encodeURIComponent(config.telegramChatId)}`
  + `&text=${encodeURIComponent(telegramText)}`;

return [{
  json: {
    prediction_date: new Date().toISOString(),
    trend_label: topLabel,
    probabilities: {
      up: Number(pUp.toFixed(6)),
      sideways: Number(pSideways.toFixed(6)),
      down: Number(pDown.toFixed(6)),
    },
    thresholds: {
      one_sigma_band: Number(sigma.toFixed(6)),
      expected_return_mu: Number(mu.toFixed(6)),
    },
    features: {
      spx_hourly_z: Number(spxH.toFixed(4)),
      spx_daily_z: Number(spxD.toFixed(4)),
      spx_weekly_z: Number(spxW.toFixed(4)),
      vix_hourly_z: Number(vixH.toFixed(4)),
      vix_daily_z: Number(vixD.toFixed(4)),
      vix_weekly_z: Number(vixW.toFixed(4)),
      latest_vix: Number(latestVix.toFixed(4)),
      news_sentiment: Number(newsSentiment.toFixed(4)),
      composite_score: Number(compositeScore.toFixed(4)),
    },
    headlines,
    telegram_text: telegramText,
    telegram_url: telegramUrl,
    notes: [
      'This workflow is a statistical signal, not investment advice.',
      'Up/Sideways/Down are defined relative to a ±1σ next-day return band around zero.',
      'Hourly, daily, and weekly SPX/VIX inputs are blended with recent news sentiment.'
    ]
  }
}];
